#!/usr/bin/env bash
# veriseal demo — seal → verify INTACT → tamper → verify TAMPERED → inspect → pack
#
# Sample: SYNTHETIC MCAP (demo/sample.mcap generated by demo/make_sample.py)
# Run from the repo root: bash demo/demo.sh

set -euo pipefail
# Prevent Git Bash on Windows from converting /topic paths to Windows paths
export MSYS_NO_PATHCONV=1
cd "$(dirname "$0")/.."

SAMPLE=demo/sample.mcap
SEAL=demo/sample.seal.json
TAMPERED=demo/tampered.mcap
KEY=demo/demo.key.pem
PUB=demo/demo.pub.pem

echo "========================================"
echo " 0. Generate synthetic sample MCAP"
echo "========================================"
python demo/make_sample.py

echo
echo "========================================"
echo " 1. Create a demo signer key, then seal (no anchor for fast demo)"
echo "========================================"
veriseal keygen --out "$KEY" --pub "$PUB" --force > /dev/null
veriseal seal "$SAMPLE" --key "$KEY" --no-anchor --out "$SEAL"

echo
echo "========================================"
echo " 2. Verify — expect INTACT"
echo "========================================"
veriseal verify "$SAMPLE" "$SEAL" --pubkey "$PUB"

echo
echo "========================================"
echo " 3. Tamper: flip byte 0 of first /pose payload"
echo "========================================"
python demo/tamper.py "$TAMPERED"

echo
echo "========================================"
echo " 4. Verify tampered copy — expect TAMPERED"
echo "========================================"
veriseal verify "$TAMPERED" "$SEAL" --pubkey "$PUB" || true   # exit 1 is expected

echo
echo "========================================"
echo " 5. Inspect incident window (+1s to +4s)"
echo "========================================"
veriseal inspect "$SAMPLE" \
    --from 2025-06-16T00:00:01Z \
    --to   2025-06-16T00:00:04Z \
    --topic /pose

echo
echo "========================================"
echo " 6. Pack — portable incident-evidence bundle"
echo "========================================"
veriseal pack "$SAMPLE" "$SEAL" --pubkey "$PUB" --out demo/incident-pack

echo
echo "Done."
